DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:HOA 010", "old_status": "partial_multi_question", "status": "ready", "question_id": "de2d1069-527e-5626-8473-6a2ab20328c6", "stem": "If a satisfies |2a−4|=5, what is the distance from a to 2 on the number line?", "choices": [{"key": "A", "text": "0.5"}, {"key": "B", "text": "2.5"}, {"key": "C", "text": "4.5"}, {"key": "D", "text": "5"}], "type": "mcq", "correct": "B", "explanation": "Since |2a−4|=2|a−2|=5, the distance |a−2| equals 2.5 for either solution a.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Page 9 contains four questions. Published original Q9 and separately Q10/Q11. Original Q8 repeats y+a=x−1 twice, giving only y+a=2 when x=3; it does not determine a and remains excluded as a defective fragment.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 9, "extra_sources": [], "parts": [{"label": "Q10", "question_id": "4852e4de-5a3f-526d-ba8f-3ed0b63d4031", "stem": "The system \\(ax-\\frac12y=c\\), \\(2x+4y=5\\) has infinitely many solutions. What is c?", "choices": [{"key": "A", "text": "\\(-5/8\\)"}, {"key": "B", "text": "\\(1/4\\)"}, {"key": "C", "text": "\\(5/4\\)"}, {"key": "D", "text": "\\(11/4\\)"}], "type": "mcq", "correct": "A", "explanation": "For infinitely many solutions the equations must be multiples. The y-coefficients require a factor (−1/2)/4=−1/8 from the second to the first. Therefore c=5(−1/8)=−5/8, and a=2(−1/8)=−1/4.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}, {"label": "Q11", "question_id": "3655bc0d-3745-5d66-97f0-5b2e241cedd2", "stem": "Using only the values in the table, which listed value of x can be confirmed to satisfy g(f(x))=x?", "choices": [{"key": "A", "text": "−3"}, {"key": "B", "text": "0"}, {"key": "C", "text": "4"}, {"key": "D", "text": "8"}], "type": "mcq", "correct": "B", "explanation": "The table gives f(0)=4 and g(4)=0, proving g(f(0))=0. For x=−3 the composition equals 20, and for x=4 it equals −7, so those do not work. For x=8, f(8)=−5 but g(−5) is not supplied, so that case cannot be confirmed. Thus only x=0 is established by the given data.", "topic": "Functions, Transformations & Graphs", "note": "Clarified “can be confirmed using only the table”: the original table omits g(−5), so it cannot disprove the x=8 option. All source values preserved.", "assets": {"html": "<table><tr><th>x</th><th>−3</th><th>−1</th><th>0</th><th>2</th><th>4</th><th>5</th><th>8</th></tr><tr><th>f(x)</th><td>2</td><td>1</td><td>4</td><td>7</td><td>−3</td><td>9</td><td>−5</td></tr><tr><th>g(x)</th><td>−7</td><td>8</td><td>−3</td><td>20</td><td>0</td><td>10</td><td>5</td></tr></table>"}}]}, {"id": "clean:HOA 014", "old_status": "partial_multi_question", "status": "ready", "question_id": "1f7be3cf-6ad7-505a-9664-35545d3e5b5c", "stem": "An employer has some documents. Giving 2 to each employee leaves 20. Instead, the employer takes 1 document, gives 3 to each employee, and has 9 left. How many documents are there?", "choices": [{"key": "A", "text": "44"}, {"key": "B", "text": "11"}, {"key": "C", "text": "10"}, {"key": "D", "text": "40"}], "type": "mcq", "correct": "D", "explanation": "Let n be the number of employees and D the documents. Then D=2n+20 and D=1+3n+9. Equating gives 2n+20=3n+10, so n=10 and D=40. Check: 20 are distributed in the first plan; in the second, 1+30+9=40.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 12, "extra_sources": [], "parts": [{"label": "Q6", "question_id": "c7ece444-c78a-58d1-8bd4-8ba233abeb6f", "stem": "If 2z−7(z−1)≤1 and z is an integer, what is the least possible value of z?", "choices": [{"key": "A", "text": "−2"}, {"key": "B", "text": "0"}, {"key": "C", "text": "2"}, {"key": "D", "text": "4"}], "type": "mcq", "correct": "C", "explanation": "Simplify to −5z+7≤1, giving −5z≤−6 and z≥6/5. The least integer meeting this bound is 2.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:HOA 015", "old_status": "partial_multi_question", "status": "ready", "question_id": "f003db31-c6a4-58d6-9479-0a3c4d8514f4", "stem": "Line d has negative slope. Line n has slope 12. Which statements may be true? I. n is perpendicular to d. II. n is parallel to d. III. n passes through (0,0).", "choices": [{"key": "A", "text": "Only I"}, {"key": "B", "text": "Only II"}, {"key": "C", "text": "I and III"}, {"key": "D", "text": "II and III"}], "type": "mcq", "correct": "C", "explanation": "I can hold if d has slope −1/12, since the product of perpendicular slopes is −1. II cannot hold because parallel nonvertical lines have equal slopes, and one slope is negative while the other is 12. III can hold for n: y=12x. Thus I and III may be true.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 13, "extra_sources": [], "parts": [{"label": "Q9", "question_id": "35b08f28-703e-50bf-b44e-a4a8829317c8", "stem": "The graph shows the speeds of Sam and Daniel. How much smaller is their speed difference at t=0.2 seconds than at t=0?", "choices": [{"key": "A", "text": "0 m/s"}, {"key": "B", "text": "0.3 m/s"}, {"key": "C", "text": "0.4 m/s"}, {"key": "D", "text": "0.6 m/s"}], "type": "mcq", "correct": "B", "explanation": "At t=0, their speeds are 0 and 0.6 m/s, a difference of 0.6 m/s. At t=0.2, Sam’s speed is 0.6 and Daniel’s is 0.3 m/s, a difference of 0.3 m/s. The difference has decreased by 0.6−0.3=0.3 m/s.", "topic": "Statistics, Probability & Data Analysis", "note": "Split original Q9 and corrected the printed answer units from seconds to meters per second.", "assets": {"figure": "data:image/jpeg;base64,"}}]}, {"id": "clean:HOA 017", "old_status": "partial_multi_question", "status": "ready", "question_id": "afdc90da-f149-5675-b606-f91d593e2971", "stem": "The 18 sorted scores are 46, 55, 60, 65, 71, 71, 76, 80, 86, 88, 89, 90, 92, 95, 98, 100, 100, 100. A 19th score is added, increasing the median. Which listed score could have been added?", "choices": [{"key": "A", "text": "74"}, {"key": "B", "text": "86"}, {"key": "C", "text": "87"}, {"key": "D", "text": "88"}], "type": "mcq", "correct": "D", "explanation": "The original median is the average of the 9th and 10th scores: (86+88)/2=87. With 19 scores the median is the 10th score. Adding 88 makes that score 88. Adding 74 or 86 makes it 86, and adding 87 makes it 87. Only 88 increases the median.", "topic": "Statistics, Probability & Data Analysis", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 15, "extra_sources": [], "parts": [{"label": "Q19", "question_id": "d93d4d79-d9f1-5ddf-979f-7644f56e87e6", "stem": "Machine A produces 30% more chips than B, and B produces twice as many as C. If A produces x chips, what is their total production?", "choices": [{"key": "A", "text": "\\(x+1.3x+2.6x\\)"}, {"key": "B", "text": "\\(x+0.3x+0.6x\\)"}, {"key": "C", "text": "\\(x+x/0.3+x/0.6\\)"}, {"key": "D", "text": "\\(x+x/1.3+x/2.6\\)"}], "type": "mcq", "correct": "D", "explanation": "Since A=1.3B and A=x, B=x/1.3. Since B=2C, C=x/2.6. Adding the three machines gives x+x/1.3+x/2.6.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:HOA 018", "old_status": "partial_multi_question", "status": "ready", "question_id": "ea439739-f34e-56b9-8a68-6e0e1deac6ad", "stem": "Which equation most closely represents the fitted line shown on the scatterplot of sales y against temperature x?", "choices": [{"key": "A", "text": "y=−1.1x+14"}, {"key": "B", "text": "y=1.1x"}, {"key": "C", "text": "y=−1.1x+12"}, {"key": "D", "text": "y=−1.8x+14"}], "type": "mcq", "correct": "A", "explanation": "The fitted line crosses the y-axis near 14 and the x-axis near 13. Its slope is approximately (0−14)/(13−0)=−1.08, closest to −1.1. Thus y=−1.1x+14 is the best match.", "topic": "Statistics, Probability & Data Analysis", "note": "Isolated and verified original Q27. Original Q26 is excluded: its fixed values already include 5 and 40, so no added x can make the range 29. Neither proposed x repairs that impossible premise.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 16, "extra_sources": [], "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:HOA 019", "old_status": "partial_multi_question", "status": "ready", "question_id": "9e745dd0-eb9f-582a-9e46-f44c92795c2d", "stem": "A circle has diameter endpoints (3,6) and (3,10). What is its equation?", "choices": [{"key": "A", "text": "\\((x-3)^2+(y-8)^2=16\\)"}, {"key": "B", "text": "\\((x-3)^2+(y+8)^2=4\\)"}, {"key": "C", "text": "\\((x+3)^2+(y+8)^2=16\\)"}, {"key": "D", "text": "\\((x-3)^2+(y-8)^2=4\\)"}], "type": "mcq", "correct": "D", "explanation": "The center is the midpoint (3,(6+10)/2)=(3,8). The diameter length is 4, so the radius is 2 and r²=4. The equation is (x−3)²+(y−8)²=4.", "topic": "Coordinate Geometry & Circles", "note": "Isolated original Q29. The upper graphs belong to PSD 029 and have been reattached there.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 17, "extra_sources": []}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260928') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260928'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260928','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
